use std::ffi::{CStr, CString};
use std::os::raw::{c_char, c_int, c_void};
use std::sync::atomic::{AtomicBool, AtomicPtr, Ordering};
use std::sync::Arc;
use std::ptr;
use std::thread;
use std::time::Duration;
use std::sync::RwLock;

// JNI-like foreign function interface for DNS resolution
// Simulates calling into a Java DNS cache via JNI

static SHUTDOWN_REQUESTED: AtomicBool = AtomicBool::new(false);

#[repr(C)]
pub struct JNIEnv {
    pub version: c_int,
    pub resolve_fn: Option<unsafe extern "C" fn(*const c_char, *mut c_char, c_int) -> c_int>,
    pub cache_invalidate_fn: Option<unsafe extern "C" fn(*const c_char) -> c_int>,
}

pub struct ResolverContext {
    env: *mut JNIEnv,
    query_count: u64,
    buffer: Vec<u8>,
    is_detached: bool,
}

unsafe impl Send for ResolverContext {}
unsafe impl Sync for ResolverContext {}

static RESOLVER_CONTEXT: once_cell::sync::Lazy<RwLock<Option<Box<ResolverContext>>>> =
    once_cell::sync::Lazy::new(|| RwLock::new(None));

impl ResolverContext {
    pub fn new(env: *mut JNIEnv) -> Self {
        ResolverContext {
            env,
            query_count: 0,
            buffer: vec![0u8; 512],
            is_detached: false,
        }
    }

    pub fn detach(&mut self) {
        self.is_detached = true;
    }

    pub fn is_valid(&self) -> bool {
        !self.env.is_null() && !self.is_detached
    }
}

/// Resolve a DNS name using the JNI bridge
pub fn resolve_hostname(hostname: &str) -> Result<String, String> {
    // Acquire read lock - prevents shutdown from invalidating context mid-use
    let guard = RESOLVER_CONTEXT.read().map_err(|_| "Lock poisoned".to_string())?;
    let ctx = match guard.as_ref() {
        Some(ctx) => ctx,
        None => return Err("Resolver not initialized".to_string()),
    };

    // Check shutdown state before proceeding
    if SHUTDOWN_REQUESTED.load(Ordering::Acquire) {
        return Err("Resolver shutting down".to_string());
    }

    if !ctx.is_valid() {
        return Err("Context invalidated".to_string());
    }

    // Validate hostname - prevent injection into JNI layer
    if hostname.len() > 253 || hostname.contains('\0') {
        return Err("Invalid hostname".to_string());
    }

    for label in hostname.split('.') {
        if label.is_empty() || label.len() > 63 {
            return Err("Invalid DNS label".to_string());
        }
        if !label.chars().all(|c| c.is_alphanumeric() || c == '-') {
            return Err("Invalid characters in hostname".to_string());
        }
    }

    let c_hostname = CString::new(hostname).map_err(|e| e.to_string())?;
    let mut result_buf = vec![0u8; 256];

    let ret = unsafe {
        let env = &*ctx.env;
        match env.resolve_fn {
            Some(resolve) => resolve(
                c_hostname.as_ptr(),
                result_buf.as_mut_ptr() as *mut c_char,
                result_buf.len() as c_int,
            ),
            None => return Err("Resolve function not available".to_string()),
        }
    };

    if ret > 0 && (ret as usize) < result_buf.len() {
        // Bound the read strictly to the returned length to avoid any
        // out-of-bounds scanning if the foreign function did not NUL-terminate.
        let written = ret as usize;
        let slice = &result_buf[..written];
        // Find the NUL terminator only within the returned bytes; if none,
        // treat the whole written region as the payload.
        let end = slice.iter().position(|&b| b == 0).unwrap_or(written);
        let result = String::from_utf8_lossy(&result_buf[..end]).into_owned();
        Ok(result)
    } else {
        Err(format!("Resolution failed with code: {}", ret))
    }
}

/// Graceful shutdown - detaches JNI context and signals workers
pub fn initiate_shutdown() {
    SHUTDOWN_REQUESTED.store(true, Ordering::Release);

    // Give in-flight requests time to complete
    thread::sleep(Duration::from_millis(100));

    // Acquire write lock - waits for all readers to finish
    if let Ok(mut guard) = RESOLVER_CONTEXT.write() {
        if let Some(ref mut ctx) = *guard {
            ctx.detach();
        }
        // Take ownership and drop, freeing memory safely
        *guard = None;
    }
}

/// Initialize the resolver with a JNI environment
pub fn initialize_resolver(env: *mut JNIEnv) -> bool {
    if env.is_null() {
        return false;
    }

    let ctx = Box::new(ResolverContext::new(env));

    if let Ok(mut guard) = RESOLVER_CONTEXT.write() {
        *guard = Some(ctx);
        SHUTDOWN_REQUESTED.store(false, Ordering::Release);
        true
    } else {
        false
    }
}

/// Background cache invalidation worker
pub fn cache_invalidation_worker(domains: Vec<String>) {
    for domain in domains {
        if SHUTDOWN_REQUESTED.load(Ordering::Acquire) {
            break;
        }

        let guard = match RESOLVER_CONTEXT.read() {
            Ok(g) => g,
            Err(_) => break,
        };

        let ctx = match guard.as_ref() {
            Some(ctx) => ctx,
            None => break,
        };

        if !ctx.is_valid() {
            break;
        }

        if let Ok(c_domain) = CString::new(domain.as_str()) {
            unsafe {
                let env = &*ctx.env;
                if let Some(invalidate) = env.cache_invalidate_fn {
                    invalidate(c_domain.as_ptr());
                }
            }
        }

        drop(guard);
        thread::sleep(Duration::from_millis(50));
    }
}
